<?php require_once '../config/auth.php'; exigirPerfil(['Administrador','Técnico','Trabalhador']); require_once '../config/conexao.php';$r=$conn->query('SELECT e.*,c.nome cliente FROM equipamentos e JOIN clientes c ON c.id=e.cliente_id ORDER BY e.id DESC'); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipamentos | HelpTech</title><link rel="stylesheet" href="../css/style.css"></head><body><header class="topbar"><a class="brand" href="../dashboard.php"><span class="brand-mark">H</span>HelpTech</a><nav class="top-actions"><a href="../logout.php">Sair ↗</a></nav></header><main class="container"><div class="page-title"><div><div class="eyebrow">Cadastros</div><h1>Equipamentos</h1><p class="subtitle">Cada equipamento deve estar associado a um cliente.</p></div><section class="panel"><div class="table-wrapper"><table><thead><tr><th>Equipamento</th><th>Marca / Modelo</th><th>Nº de série</th><th>Cliente</th><th>Ações</th></tr></thead><tbody><?php if($r&&$r->num_rows):while($e=$r->fetch_assoc()):?><tr><td><?= h($e['tipo']) ?></td><td><?= h(trim(($e['marca']??'').' '.($e['modelo']??''))) ?></td><td><?= h($e['numero_serie']) ?></td><td><?= h($e['cliente']) ?></td><td><a class="button secondary small" href="editar.php?id=<?= (int)$e['id'] ?>">Editar</a> <a class="button danger small" data-confirm="Excluir este equipamento?" href="excluir.php?id=<?= (int)$e['id'] ?>">Excluir</a></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">Nenhum equipamento cadastrado.</td></tr><?php endif;?></tbody></table></div></section></main><script src="../js/script.js"></script></body></html>